<script lang="ts">
 import {invoke} from '@tauri-apps/api/core';import {onDestroy,onMount} from 'svelte';
 import type {ChannelMember} from './teams';
 let {teamId,channelId,ownId,onChanged,onClose}:{teamId:string;channelId?:string;ownId:string;onChanged:()=>void;onClose:()=>void}=$props();
 let roster=$state<{rows:ChannelMember[];kind:string;canManage:boolean;reason:string}|null>(null),busy=$state(false),error=$state(''),uncertain=$state(false),query=$state(''),people=$state<{id:string;displayName?:string}[]>([]),choice=$state<{action:string;id:string;memberId:string;name:string}|null>(null);
 let alive=true,serial=0;onDestroy(()=>{alive=false;serial++;});const target=()=>({teamId,channelId:channelId??null,ownId});
 onMount(()=>{void load();});
 async function load(){if(busy)return;busy=true;error='';const v=++serial;try{const result=await invoke<NonNullable<typeof roster>>('collaboration_roster',{target:target()});if(alive&&v===serial){roster=result;uncertain=false;choice=null;}}catch(e){if(alive&&v===serial)error=String(e);}finally{if(alive&&v===serial)busy=false;}}
 async function search(){if(busy||query.trim().length<2)return;busy=true;error='';const v=++serial;try{const r=await invoke<{value:typeof people}>('graph_search_users',{query});if(alive&&v===serial)people=r.value??[];}catch(e){if(alive&&v===serial)error=String(e);}finally{if(alive&&v===serial)busy=false;}}
 async function change(){if(!choice||busy||uncertain)return;busy=true;error='';const saved=choice;const v=++serial;try{const r=await invoke<{status:string;error?:string}>('collaboration_member_change',{target:target(),action:saved.action,userId:saved.id,memberId:saved.memberId});if(!alive||v!==serial)return;choice=null;people=[];query='';if(r.status!=='confirmed'){uncertain=true;error=r.error??'Membership change not confirmed.';}else{busy=false;await load();onChanged();}}catch(e){if(alive&&v===serial){error=String(e);choice=null;}}finally{if(alive)busy=false;}}
</script>
<div class="membership-manager" role="dialog" aria-label="Manage membership">
 <div class="manager-head"><h3>Manage {roster?.kind==='standard'?'team':'channel'} members</h3><button disabled={busy} onclick={onClose}>Close</button></div>
 <p>{roster?.reason??'Reading current membership and permissions…'}</p><button class="detail-button" disabled={busy} onclick={load}>Refresh roster</button>
 {#if busy}<p role="status">Working…</p>{/if}{#if error}<p role="alert">{error}</p>{/if}
 {#each roster?.rows??[] as member(member.id)}<div class="manager-row"><span>{member.displayName||'Participant unavailable'}{member.userId===ownId?' (You)':''}<small>{member.roles?.includes('owner')?'Owner':'Member'}</small></span>{#if !member.roles?.includes('owner')&&!member['@microsoft.graph.originalSourceMembershipUrl']&&(roster?.canManage||member.userId===ownId)}<button disabled={busy||uncertain} onclick={()=>choice={action:'remove',id:member.userId!,memberId:member.id,name:member.displayName??'this member'}}>{member.userId===ownId?'Leave':'Remove'}</button>{/if}</div>{/each}
 {#if roster?.canManage}<label>Find a coworker<input aria-label="Find membership coworker" bind:value={query} disabled={busy||uncertain}/></label><button disabled={busy||uncertain||query.trim().length<2} onclick={search}>Search coworkers</button>{#each people.filter(p=>!roster?.rows.some(m=>m.userId===p.id)) as person}<button class="person-choice" disabled={busy||uncertain} onclick={()=>choice={action:'add',id:person.id,memberId:'',name:person.displayName??'coworker'}}>Add {person.displayName??'coworker'}</button>{/each}{/if}
 {#if choice}<section class="membership-confirm" aria-label="Confirm membership change"><p>{choice.action==='add'?'Add':'Remove'} {choice.name}{roster?.kind==='standard'?' in the entire team and its standard channels':' in this channel'}?</p><button disabled={busy} onclick={()=>choice=null}>Cancel</button><button disabled={busy||uncertain} onclick={change}>Confirm {choice.action==='add'?'add':'remove'}</button></section>{/if}
</div>
<style>.membership-manager{border:1px solid var(--border-strong);border-radius:9px;padding:14px;margin-top:15px;background:var(--surface-panel)}.manager-head{display:flex;justify-content:space-between;gap:10px}.manager-head h3{font-size:13px;margin:0}.membership-manager p{font-size:11px;color:var(--text-secondary);line-height:1.6}.membership-manager button{color:var(--accent);font-size:11px;padding:8px;border:1px solid var(--border-strong);border-radius:5px;margin:5px 3px 5px 0}.manager-row{display:flex;justify-content:space-between;align-items:center;font-size:12px;padding:10px 0;border-bottom:1px solid var(--border);overflow-wrap:anywhere}.manager-row small{display:block;color:var(--text-secondary);font-size:10px;margin-top:5px}.membership-manager label{display:block;font-size:11px;margin-top:15px}.membership-manager input{display:block;width:100%;box-sizing:border-box;background:var(--surface-base);color:var(--text-primary);padding:8px;border:1px solid var(--border-strong);border-radius:5px;margin-top:7px}.membership-confirm{padding:10px;border:1px solid var(--accent)}[role=alert]{color:var(--error)!important}.person-choice{display:block}</style>
